  ('e1140129-5679-4dbd-a256-3ef0946cc817', $$Wiskunde A$$, $$HAVO$$, $$Huisartsenzorg$$, $$HAVO Wiskunde A 2023-I$$),
  ('827e0430-ff97-4b32-add0-01ded2de5f61', $$Wiskunde A$$, $$HAVO$$, $$Mobiel dataverbruik$$, $$HAVO Wiskunde A 2023-I$$),
  ('8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$Wiskunde A$$, $$HAVO$$, $$Bewegen jongeren genoeg?$$, $$HAVO Wiskunde A 2023-I$$),
  ('06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$Wiskunde A$$, $$HAVO$$, $$Formules in de F1$$, $$HAVO Wiskunde A 2023-I$$),
  ('3389d020-c73d-412d-bc09-2cf0f92ea239', $$Wiskunde A$$, $$HAVO$$, $$Wel het huis, maar niet de grond$$, $$HAVO Wiskunde A 2023-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('db199f04-a76e-416f-b05b-d4657ccf5ec4', 'e1140129-5679-4dbd-a256-3ef0946cc817', $$inleiding$$,
   $$wiskunde-a-havo-2023-i-huisartsenzorg-context1.png$$,
   $$De uitgaven aan huisartsenzorg voor één persoon per jaar kan je volgens een eenvoudig model berekenen met de volgende formule:$$, 'inline'),
  ('4637afb0-91e8-4e36-8c6a-13c92b793307', 'e1140129-5679-4dbd-a256-3ef0946cc817', $$formule 1$$,
   $$wiskunde-a-havo-2023-i-huisartsenzorg-context2.png$$,
   $$U = 60 + 10 · A (formule 1)$$, 'inline'),
  ('2a26b2fa-9e0e-4350-a63b-b1e6b7cec1f2', 'e1140129-5679-4dbd-a256-3ef0946cc817', $$toelichting formule 1$$,
   $$wiskunde-a-havo-2023-i-huisartsenzorg-context3.png$$,
   $$Hierin is U het bedrag in euro dat voor één persoon per jaar aan huisartsenzorg wordt uitgegeven en A het aantal huisartsconsulten van die persoon per jaar.$$, 'inline'),
  ('ee5263d3-1525-4cba-8334-f3aa4bcfca19', 'e1140129-5679-4dbd-a256-3ef0946cc817', $$aantal consulten in 2018$$,
   $$wiskunde-a-havo-2023-i-huisartsenzorg-context4.png$$,
   $$In 2018 was het gemiddelde aantal huisartsconsulten per persoon gelijk aan 4,5.$$, 'inline'),
  ('666ec04f-c5b4-4d57-ab35-cb8cc44f003b', 'e1140129-5679-4dbd-a256-3ef0946cc817', $$stijging 10% in 2020$$,
   $$wiskunde-a-havo-2023-i-huisartsenzorg-context5.png$$,
   $$Stel dat in 2020 het gemiddelde aantal huisartsconsulten per persoon 10% hoger was dan in 2018. Volgens formule 1 zouden in 2020 de gemiddelde uitgaven aan huisartsenzorg dan ook hoger zijn geweest dan in 2018.$$, 'inline'),
  ('6525e15b-b645-4625-8d83-a081007e5669', 'e1140129-5679-4dbd-a256-3ef0946cc817', $$gemiddelde waarden$$,
   $$wiskunde-a-havo-2023-i-huisartsenzorg-context6.png$$,
   $$In de rest van de opgave bedoelen we met de uitdrukkingen ‘het aantal huisartsconsulten’ en ‘de uitgaven aan huisartsenzorg’ steeds de gemiddelde waarden.$$, 'inline'),
  ('c456154a-ab16-4b53-993a-63b4d25dd948', 'e1140129-5679-4dbd-a256-3ef0946cc817', $$inleiding formule 2$$,
   $$wiskunde-a-havo-2023-i-huisartsenzorg-context7.png$$,
   $$Voor ouderen is het aantal huisartsconsulten per persoon per jaar hoger dan voor jongeren. Voor personen van 5 jaar tot en met 64 jaar geldt voor het aantal huisartsconsulten per persoon per jaar A de volgende formule:$$, 'inline'),
  ('4e08ccb5-43c8-4a17-a64e-a57d72ffb751', 'e1140129-5679-4dbd-a256-3ef0946cc817', $$formule 2$$,
   $$wiskunde-a-havo-2023-i-huisartsenzorg-context8.png$$,
   $$A = 1,75 + 0,05 · l (formule 2)
Hierin is l de leeftijd van de persoon in jaren.$$, 'inline'),
  ('8845eaac-f51b-4b7f-9b99-342873f75df5', 'e1140129-5679-4dbd-a256-3ef0946cc817', $$gecombineerde formule$$,
   $$wiskunde-a-havo-2023-i-huisartsenzorg-context9.png$$,
   $$Door de formules 1 en 2 te combineren kan voor personen van 5 jaar tot en met 64 jaar een formule worden afgeleid waarin de uitgaven aan huisartsenzorg per persoon per jaar (U) worden uitgedrukt in de leeftijd (l) van de persoon.
Deze formule kan worden geschreven in de vorm U = ... · l + ... waarbij op de puntjes getallen staan.$$, 'inline'),
  ('be07b09d-d173-44e5-bd52-12b132aea1ed', 'e1140129-5679-4dbd-a256-3ef0946cc817', $$lineair verband 65 jaar en ouder$$,
   $$wiskunde-a-havo-2023-i-huisartsenzorg-context10.png$$,
   $$We kijken nu naar personen van 65 jaar of ouder. Neem ook voor deze leeftijdsgroep aan dat het verband tussen het aantal huisartsconsulten per persoon per jaar (A) en de leeftijd in jaren (l) lineair is. Voor personen van 65 jaar is het aantal huisartsconsulten per persoon per jaar gelijk aan 5. Voor personen van 80 jaar is dit aantal gelijk aan 9.$$, 'inline'),
  ('078b87f5-ee9f-4710-adeb-5d24752be5d1', '827e0430-ff97-4b32-add0-01ded2de5f61', $$inleiding$$,
   $$wiskunde-a-havo-2023-i-mobiel-dataverbruik-context1.png$$,
   $$Op de hele wereld gebruiken mensen hun mobiele telefoon steeds meer. De hoeveelheid verbruikte mobiele data neemt daardoor elk jaar toe.
In Nederland was in 2017 het totale mobiele dataverbruik 325 miljoen gigabyte (GB), een stijging van 1050% ten opzichte van 2013.$$, 'inline'),
  ('22a5cf89-f55a-40ee-87ff-cc14c3db39e6', '827e0430-ff97-4b32-add0-01ded2de5f61', $$figuur 1: mobiel dataverbruik per simkaart per maand$$,
   $$wiskunde-a-havo-2023-i-mobiel-dataverbruik-context2.png$$,
   $$In figuur 1 is te zien dat het mobiele dataverbruik per simkaart¹⁾ in diverse Europese landen in de periode 2008-2017 enorm is gestegen.
figuur 1 mobiel dataverbruik per simkaart per maand$$, 'inline'),
  ('64462792-e5fd-412a-af07-f76f1eba11cb', '827e0430-ff97-4b32-add0-01ded2de5f61', $$dataverbruik Finland 2013-2017$$,
   $$wiskunde-a-havo-2023-i-mobiel-dataverbruik-context3.png$$,
   $$Je kunt in figuur 1 aflezen dat in Finland in het jaar 2013 het mobiele dataverbruik per simkaart 1,6 GB per maand was. Dit was in 2017 gegroeid naar 12,0 GB per maand. Neem aan dat er in deze periode sprake was van exponentiële groei.$$, 'inline'),
  ('25b9006c-3ce8-4417-947c-fc876de017c9', '827e0430-ff97-4b32-add0-01ded2de5f61', $$noot simkaart$$,
   $$wiskunde-a-havo-2023-i-mobiel-dataverbruik-context4.png$$,
   $$noot 1 Een simkaart is een chip die in een mobiel apparaat gedaan wordt. In deze opgave wordt steeds het gemiddelde mobiele dataverbruik per simkaart bedoeld. SIM staat voor Subscriber Identity Module.$$, 'inline'),
  ('f75e4faf-6298-4b02-a86c-7aa1f891eafb', '827e0430-ff97-4b32-add0-01ded2de5f61', $$vergelijking Finland en Nederland$$,
   $$wiskunde-a-havo-2023-i-mobiel-dataverbruik-context5.png$$,
   $$In 2017 was het mobiele dataverbruik per simkaart per maand in Finland 12 keer zo groot als in Nederland. Dit is deels te verklaren door het feit dat het dataverbruik in Finland een stuk goedkoper was. De providers in Nederland brachten in 2017 gemiddeld ongeveer 14 keer zoveel in rekening als de providers in Finland voor het verbruik van dezelfde hoeveelheid mobiele data.$$, 'inline'),
  ('d9149421-9526-4ccf-b4bd-0a3e204e3c6b', '827e0430-ff97-4b32-add0-01ded2de5f61', $$figuur 2: prijs en verbruik$$,
   $$wiskunde-a-havo-2023-i-mobiel-dataverbruik-context6.png$$,
   $$In figuur 2 is voor het jaar 2017 het verband tussen de gemiddelde prijs (P) van het mobiele dataverbruik en het verbruik (V) per simkaart per maand weergegeven.
figuur 2$$, 'inline'),
  ('dfdde0c1-dd2f-4491-969f-8cb991d61681', '827e0430-ff97-4b32-add0-01ded2de5f61', $$omgekeerd evenredig verband$$,
   $$wiskunde-a-havo-2023-i-mobiel-dataverbruik-context7.png$$,
   $$In figuur 2 is te zien: hoe hoger de prijs in een bepaald land is, hoe lager het dataverbruik. Bij de trendlijn hoort een omgekeerd evenredig verband.$$, 'inline'),
  ('b97fb0f9-dfeb-4376-838f-4887c7c1752b', '827e0430-ff97-4b32-add0-01ded2de5f61', $$inleiding tabel$$,
   $$wiskunde-a-havo-2023-i-mobiel-dataverbruik-context8.png$$,
   $$In figuur 1 zie je bij de vier Europese landen dat het mobiele dataverbruik toenemend stijgt. In Zuid-Korea en Japan, die niet zijn opgenomen in figuur 1, is de sterke groei al wat afgenomen. In de tabel staan de gegevens van deze landen van de jaren 2014 en 2015.$$, 'inline'),
  ('2a28fa60-4bf4-4b28-9896-cf9ce5b78cab', '827e0430-ff97-4b32-add0-01ded2de5f61', $$tabel: dataverbruik Zuid-Korea en Japan$$,
   $$wiskunde-a-havo-2023-i-mobiel-dataverbruik-context9.png$$,
   $$tabel mobiel dataverbruik per simkaart per maand
| | 2014 | 2015 |
| Zuid-Korea | 1,711 GB | 2,198 GB |
| Japan | 1,631 GB | 1,945 GB |
Neem aan dat de toename van het mobiele dataverbruik per simkaart per maand in beide landen vanaf 2014 lineair is. Dan zal men in Zuid-Korea eerder gemiddeld 10 GB per simkaart per maand verbruiken dan in Japan.$$, 'inline'),
  ('d2c2c137-1720-45cf-8068-70ef62b43601', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$foto$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context1.png$$,
   $$$$, 'inline'),
  ('50cc7fb0-11b7-4967-bfcb-5010be6b6d61', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$inleiding onderzoek$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context2.png$$,
   $$Het lijkt erop dat een aanzienlijk deel van de jongeren in Nederland te weinig beweegt. Het onderzoek ‘Health Behaviour in School-aged Children’ dat sinds 1985 uitgevoerd wordt, bevat informatie over het beweeggedrag van jongeren in Nederland. Deze opgave gaat over het deel van dit onderzoek dat betrekking heeft op jongeren in het reguliere voortgezet onderwijs in de eerste vier leerjaren. Deze groep beschouwen we in deze opgave als de onderzoekspopulatie. Aan het onderzoek deden 67 scholen mee. We nemen aan dat deze groep scholen een aselecte en representatieve steekproef vormt uit alle scholen voor regulier voortgezet onderwijs.$$, 'inline'),
  ('5147618f-ac41-45fa-b492-4ed557e8a8d5', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$steekproefmethode$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context3.png$$,
   $$Onder de deelnemende scholen waren er scholen met een groot aantal klassen en scholen met een klein aantal klassen. De onderzoekers kregen van deze scholen een lijst van alle klassen van de eerste vier leerjaren. Uit elke lijst trokken de onderzoekers vervolgens aselect uit elk leerjaar één klas. Alle leerlingen uit die getrokken klassen deden mee aan het onderzoek.$$, 'inline'),
  ('38cc6439-8a36-4c3b-ab5f-1b492b132b5a', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$geen aselecte steekproef$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context4.png$$,
   $$De leerlingen die op deze manier in de steekproef terecht zouden komen, vormen geen aselecte steekproef uit de onderzoekspopulatie.$$, 'inline'),
  ('33cb80d7-84e5-4e6f-b844-d7aed4d4e381', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$probleem opgelost$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context5.png$$,
   $$De onderzoekers hebben het bovengenoemde probleem uiteindelijk opgelost. In de rest van de opgave nemen we aan dat de steekproef aselect en representatief is.$$, 'inline'),
  ('f43fcc5b-e5bf-45dd-8ab3-66bba68fe6bc', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$vragen over bewegen$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context6.png$$,
   $$Aan de leerlingen zijn onder andere de volgende vragen over bewegen gesteld: − Doe je minstens twee keer per week aan sport of speel je minstens twee keer per week buiten? − Ben je lid van een sportclub? − Op hoeveel dagen van de afgelopen zeven dagen was je ten minste één uur per dag bezig met lichaamsbeweging?$$, 'inline'),
  ('0609563b-716a-46c2-b32b-3a76ad4df68f', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$kenmerken van leerlingen$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context7.png$$,
   $$Van de leerlingen waren een aantal kenmerken bekend, zoals: − geslacht (meisje, jongen) − schoolniveau (vmbo, havo, vwo) − gezinswelvaart (laag, midden, hoog)$$, 'inline'),
  ('274ea801-34e7-4451-beb9-b71acea897b2', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$kwalitatieve variabelen$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context8.png$$,
   $$De drie genoemde kenmerken zijn kwalitatieve variabelen.$$, 'inline'),
  ('7756db4a-7f4b-4180-aca4-0187426a6739', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$inleiding tabel 1$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context9.png$$,
   $$In tabel 1 is te zien hoeveel meisjes en hoeveel jongens aan het onderzoek deelnamen. Ook is te zien hoeveel procent van de meisjes en hoeveel procent van de jongens minstens twee keer per week sport of buiten speelt.$$, 'inline'),
  ('8128ba77-e422-4759-920d-7d6c2e757f8d', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$tabel 1$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context10.png$$,
   $$tabel 1
| | meisjes | jongens | totaal |
| aantal deelnemers onderzoek | 2736 | 2835 | 5571 |
| percentage dat minstens twee keer per week sport of buiten speelt | 76,4 | 84,2 | 80,4 |$$, 'inline'),
  ('135063a2-3099-41d1-b394-9bf645f45fd7', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$betrouwbaarheidsintervallen$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context11.png$$,
   $$Je kunt nu het 95%-betrouwbaarheidsinterval berekenen voor de populatieproportie van het aantal meisjes dat minstens twee keer per week sport of buiten speelt. Hetzelfde kun je doen voor de jongens.$$, 'inline'),
  ('c526e148-795c-48f5-833d-f21516c95140', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$inleiding tabel 2$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context12.png$$,
   $$In tabel 2 zie je het aantal leerlingen dat aan het onderzoek deelnam uitgesplitst naar schoolniveau, met daarbij het aantal leerlingen dat lid is van een sportclub.$$, 'inline'),
  ('fb4cf73c-3ffc-4af3-9fcd-e7bdbfb17f25', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$tabel 2$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context13.png$$,
   $$tabel 2
| | vmbo | havo | vwo |
| aantal deelnemers onderzoek | 2745 | 1612 | 1214 |
| aantal dat lid is van een sportclub | 1779 | 1188 | 981 |$$, 'inline'),
  ('cc797fa4-a935-4657-b58d-18393745d03a', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$verschil havo en vwo$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context14.png$$,
   $$Op basis van tabel 2 kun je een uitspraak doen over het verschil tussen het aantal havo-leerlingen en het aantal vwo-leerlingen in Nederland dat lid is van een sportclub.$$, 'inline'),
  ('fa45f69b-f622-4203-90bf-e953e54b9860', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$inleiding tabel 3$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context15.png$$,
   $$In tabel 3 staat het aantal deelnemende leerlingen en het gemiddelde aantal dagen dat zij in de afgelopen zeven dagen minstens één uur per dag bezig waren met lichaamsbeweging, uitgesplitst naar gezinswelvaart.$$, 'inline'),
  ('bdc529c5-28c9-4817-ba0c-de09d3abe077', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$tabel 3$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context16.png$$,
   $$tabel 3
| gezinswelvaart | laag | midden | hoog |
| aantal deelnemers onderzoek | 680 | 3097 | 1794 |
| gemiddeld aantal dagen met minstens één uur lichaamsbeweging | 3,8 | 4,2 | 4,6 |$$, 'inline'),
  ('2318b419-e2b0-4100-b1c1-513021d038d1', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$effectgrootte$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context17.png$$,
   $$Op basis van tabel 3 wil Yarah het gemiddelde aantal dagen (met minstens één uur lichaamsbeweging) van de groepen laag en hoog met elkaar vergelijken. Hierbij wil Yarah gebruikmaken van de effectgrootte zoals die op het formuleblad is weergegeven.$$, 'inline'),
  ('f2e10171-af79-45ee-804d-266a3d470333', '8370c4d6-9e89-47e0-b3a2-04a7954b4b0a', $$standaardafwijkingen gelijk$$,
   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-context18.png$$,
   $$Veronderstel dat de standaardafwijking S₁ voor de groep met lage gezinswelvaart even groot is als de standaardafwijking S₂ voor de groep met hoge gezinswelvaart, dus S₁ = S₂ = S.$$, 'inline'),
  ('124b99d7-32d2-4414-a42b-801a4d6b7825', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$inleiding$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context1.png$$,
   $$Formule 1 (F1) is de hoogste klasse in de autosport. Gedurende het jaar worden er races gehouden op circuits in verschillende landen. In deze opgave kijken we naar enkele formules in de F1 die het verschil kunnen bepalen tussen winnen en verliezen.$$, 'inline'),
  ('07ff9fa0-d2ac-4619-aa7d-9cd6ab86f4bc', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$straal van een bocht$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context2.png$$,
   $$In een F1-race moet de coureur steeds inschatten met welke snelheid hij een bocht kan nemen. Voor de scherpte van de bocht geldt: hoe kleiner de straal r van de bocht, hoe scherper de bocht. Zie de figuur.$$, 'inline'),
  ('2ebe5a9c-82c4-485c-9177-a95fa252ecb0', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$figuur: scherpe en flauwe bocht$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context3.png$$,
   $$figuur
scherpe bocht | flauwe bocht$$, 'inline'),
  ('1ce182f2-b9b9-4f8c-80de-593f7f5bb6da', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$maximale bochtensnelheid$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context4.png$$,
   $$Als de coureur sneller rijdt dan de maximale bochtensnelheid v, vliegt hij uit de bocht. Onder bepaalde omstandigheden geldt voor een bepaald type F1-auto het volgende verband tussen v en r:$$, 'inline'),
  ('4783ce95-c633-4e65-8e68-d58678d5df44', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$formule 1$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context5.png$$,
   $$r = (4,026 · v²) / (7644 + 0,1929 · v²)⁰,⁸ (formule 1)$$, 'inline'),
  ('1ccf987a-ca38-4e1e-bc41-4dbf186caf48', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$toelichting formule 1$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context6.png$$,
   $$Hierin is r de straal van de bocht in meter en v de maximale bochtensnelheid in km per uur.$$, 'inline'),
  ('520272ee-d762-4eac-86c8-8dfc38fcaa93', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$bocht met straal 80 meter$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context7.png$$,
   $$Een coureur nadert een bocht met een straal van 80 meter.$$, 'inline'),
  ('5859737e-e250-4700-af68-9aa78078c5fc', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$schets grafiek op uitwerkbijlage$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context8.png$$,
   $$Op de uitwerkbijlage staat een schets van de grafiek die hoort bij het verband van formule 1. In deze schets is de maximale bochtensnelheid v uitgezet tegen de straal r van de bocht.$$, 'inline'),
  ('2da4da5a-266d-4eb3-a384-aca5b3aa7ebd', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$pitstops$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context9.png$$,
   $$Omdat de banden gedurende de race slijten, verliezen ze grip op het wegdek en lopen de rondetijden op. Daarom worden tijdens zogeheten pitstops de banden te verwisseld voor nieuwe, maar dat wisselen kost wel tijd (pitstraat inrijden, banden wisselen, pitstraat uitrijden).$$, 'inline'),
  ('61c10262-9957-461a-94ec-cebf89869cae', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$inleiding formule 2$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context10.png$$,
   $$Voor een bepaald type F1-auto kan het totale tijdverlies T in een race als gevolg van slijtage van de banden en het aantal pitstops, worden gegeven door de formule:$$, 'inline'),
  ('9a82c9df-e65d-4051-b9fb-8f10dfe6ec0d', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$formule 2$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context11.png$$,
   $$T = (0,5 · b · L²) / (n + 1) + n · P (formule 2)$$, 'inline'),
  ('8b08b97f-f9a2-4d45-9674-34e563794561', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$toelichting formule 2$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context12.png$$,
   $$Hierin is: − T het totale tijdverlies in seconden − b de bandenslijtage, een getal dat onder andere afhangt van het circuit − L het aantal ronden van de race − n het aantal pitstops in de race − P het gemiddelde tijdverlies in seconden per pitstop$$, 'inline'),
  ('b345d8a4-d650-4c99-b2be-6a0b5f1fea5c', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$race van 60 ronden$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context13.png$$,
   $$Als we bij een race van 60 ronden uitgaan van een bandenslijtage van 0,1 en een gemiddeld tijdverlies van 20 seconden per pitstop, dan kunnen we formule 2 herleiden tot de formule:$$, 'inline'),
  ('d60e12dd-de9f-4f77-a95d-c47ccea424a6', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$formule 3$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context14.png$$,
   $$T = (20n² + 20n + 180) / (n + 1) (formule 3)$$, 'inline'),
  ('40c1608f-1581-4aa1-a05c-ec3c65ef6336', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$afname tijdverlies per pitstop$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context15.png$$,
   $$Als het gemiddelde tijdverlies per pitstop zou kunnen afnemen, dan kan het optimale aantal pitstops misschien toenemen om het totale tijdverlies in de race zo klein mogelijk te houden.$$, 'inline'),
  ('cacd74bc-5597-43ae-88c2-e49acc9b1ba0', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$race van 45 ronden$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context16.png$$,
   $$Op een ander circuit, waar de race 45 ronden duurt, geldt voor een bepaalde F1-auto een bandenslijtage van 0,3. Je kunt dan met de volgende formule het optimale aantal pitstops bepalen:$$, 'inline'),
  ('76196f81-4c7f-466e-bba1-15b349bf0823', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$formule 4$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context17.png$$,
   $$N = −1 + 45 · √(3 / (20P)) (formule 4)$$, 'inline'),
  ('52ce41be-9cba-4a00-bd8a-4853bc6c420c', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$toelichting formule 4$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context18.png$$,
   $$Hierin is N het (onafgeronde) optimale aantal pitstops en P het gemiddelde tijdverlies in seconden per pitstop.$$, 'inline'),
  ('9b23ec88-9d2f-4c27-9851-5358e87b9f72', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$tijdverlies 24,8 seconden$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context19.png$$,
   $$Op dit circuit geldt voor deze F1-auto dat het gemiddelde tijdverlies van een pitstop 24,8 seconden is. Uit de formule volgt dan dat N ongeveer 2,5 is. Er moet een keuze gemaakt worden of er nu 2 of 3 pitstops moeten plaatsvinden. Deze keuze zou makkelijker zijn als N precies 3 was geweest.$$, 'inline'),
  ('64c1464a-e906-4e8f-829c-281d9275bbb7', '06bd5e5b-6dfd-4b5f-9758-f5562f68c766', $$uitwerkbijlage vraag 16$$,
   $$wiskunde-a-havo-2023-i-formules-in-de-f1-context20.png$$,
   $$16
v (km/u)
r (m)$$, 'uitwerkbijlage'),
  ('30764cc0-1a91-4365-a875-0e90fcabee5f', '3389d020-c73d-412d-bc09-2cf0f92ea239', $$inleiding duo-koop$$,
   $$wiskunde-a-havo-2023-i-wel-het-huis-maar-niet-de-grond-context1.png$$,
   $$Als je een huis koopt, word je normaal gesproken niet alleen eigenaar van het huis, maar ook van de grond waar het huis op staat.
Voor de betaling sluit de koper meestal een hypotheek af. Dit is een lening die in maandelijkse termijnen met rente moet worden terugbetaald binnen een afgesproken termijn, de zogenoemde looptijd.
Soms wil een koper een huis kopen waarvoor de bank geen hypotheek wil geven omdat het huis eigenlijk te duur is voor de koper. In zo’n geval kan de koper besluiten tot duo-koop. Je koopt dan wel het huis, maar niet de grond. De maandelijkse hypotheekkosten zijn dan lager, maar er moet dan ook een maandelijks bedrag voor het huren van de grond worden betaald.$$, 'inline'),
  ('9adb5bd9-ea11-48bf-8736-a8834197700e', '3389d020-c73d-412d-bc09-2cf0f92ea239', $$grondpercentage en huurpercentage$$,
   $$wiskunde-a-havo-2023-i-wel-het-huis-maar-niet-de-grond-context2.png$$,
   $$Bij duo-koop wordt de huurprijs van de grond bepaald aan de hand van twee percentages: − G: het grondpercentage, dat is de procentuele waarde van de grond ten opzichte van de prijs van huis en grond samen. − H: het huurpercentage, dat is het percentage van de waarde van de grond dat jaarlijks aan huur voor de grond betaald moet worden.
Bijvoorbeeld: voor een huis dat inclusief de grond € 200 000 kost en waarvoor geldt dat G = 25 en H = 6, is de waarde van de grond € 50 000 en zal bij duo-koop de huur van de grond € 3000 per jaar, dus € 250 per maand zijn.$$, 'inline'),
  ('963611b3-f406-452a-a965-1ecf5dc6ce2b', '3389d020-c73d-412d-bc09-2cf0f92ea239', $$huis in Den Haag$$,
   $$wiskunde-a-havo-2023-i-wel-het-huis-maar-niet-de-grond-context3.png$$,
   $$Nicolette en Fouad willen een huis kopen in Den Haag. Het huis kost inclusief de grond € 240 000. Ze willen hiervoor een hypotheek afsluiten met een looptijd van 30 jaar. In de tabel staat een aanbieding van een bank voor beide manieren van kopen.$$, 'inline'),
  ('2e3c0eef-cb8e-43a0-afdd-996c5bff29f2', '3389d020-c73d-412d-bc09-2cf0f92ea239', $$tabel: kosten gewone koop en duo-koop$$,
   $$wiskunde-a-havo-2023-i-wel-het-huis-maar-niet-de-grond-context4.png$$,
   $$tabel Kosten voor een huis (inclusief grond) van € 240 000
| gewone koop | duo-koop | |
| huis en grond (koop) | huis (koop) | grond (huur) |
| hypotheekkosten € 774 per maand | hypotheekkosten € 505 per maand | G = 35; H = 1,5 |$$, 'inline'),
  ('c241ca83-0b2c-492e-b575-232ee9577d9b', '3389d020-c73d-412d-bc09-2cf0f92ea239', $$vaste kosten en percentages$$,
   $$wiskunde-a-havo-2023-i-wel-het-huis-maar-niet-de-grond-context5.png$$,
   $$De hypotheekkosten en de huurprijs van de grond veranderen niet tijdens de looptijd. We nemen aan dat de percentages G en H ook niet veranderen tijdens de looptijd.$$, 'inline'),
  ('97a6f58e-4aea-4521-abf5-183c5a278389', '3389d020-c73d-412d-bc09-2cf0f92ea239', $$waardestijging 2% per jaar$$,
   $$wiskunde-a-havo-2023-i-wel-het-huis-maar-niet-de-grond-context6.png$$,
   $$Het huis en de grond worden in de loop van de 30 jaar meer waard. We nemen aan dat de waarde van zowel het huis als de grond jaarlijks met 2% toeneemt.$$, 'inline'),
  ('a0ff5d04-bdae-4698-a9ab-874507e1938b', '3389d020-c73d-412d-bc09-2cf0f92ea239', $$overweging duo-koop$$,
   $$wiskunde-a-havo-2023-i-wel-het-huis-maar-niet-de-grond-context7.png$$,
   $$Nicolette en Fouad overwegen het huis met duo-koop te kopen. Daarmee zijn de maandelijkse kosten lager dan bij de gewone koop.$$, 'inline'),
  ('46149c54-f2eb-41d1-b606-9ff596c64c9b', '3389d020-c73d-412d-bc09-2cf0f92ea239', $$grond kopen na 30 jaar$$,
   $$wiskunde-a-havo-2023-i-wel-het-huis-maar-niet-de-grond-context8.png$$,
   $$Na de looptijd van 30 jaar verwachten ze voldoende geld te hebben om de grond alsnog te kopen, uiteraard voor de prijs die de grond op dat moment waard is. Dit zal betekenen dat de totale kosten over de looptijd van 30 jaar bij duo-koop hoger zullen zijn dan bij gewone koop.$$, 'inline'),
  ('8136dc71-ec2c-4a44-a5a0-2aa53bbcc947', '3389d020-c73d-412d-bc09-2cf0f92ea239', $$voorwaarde voor de koop$$,
   $$wiskunde-a-havo-2023-i-wel-het-huis-maar-niet-de-grond-context9.png$$,
   $$Nicolette en Fouad willen het huis met duo-koop kopen als de totale kosten daarbij minder dan € 100 000 hoger zijn dan bij gewone koop. Als dat niet zo is, gaat de koop niet door.$$, 'inline');

