   $$wiskunde-a-havo-2023-i-bewegen-jongeren-genoeg-vraag11.png$$, $$3p 11 Geef van elk van de drie kenmerken aan of het wel of geen ordinale variabele is. Licht bij elk kenmerk je antwoord toe.$$, array['0609563b-716a-46c2-b32b-3a76ad4df68f', '274ea801-34e7-4451-beb9-b71acea897b2']::uuid[]),
