   '["betrouwbaarheidsinterval", "populatieproportie", "steekproefproportie", "standaardfout", "intervallen vergelijken", "formuleblad"]'::jsonb,
   $$Twee 95%-betrouwbaarheidsintervallen voor een populatieproportie berekenen en nagaan of ze overlappen.$$,
